// De todos los archivos en /upload, elige el .csv mas reciente por nombre.
// El nombre trae fecha y hora (settlement...-YYYY-MM-DD-HHMMSS.csv), asi que
// ordenar alfabeticamente descendente = el mas nuevo primero.
const items = $input.all();

const files = items
  .map(i => i.json)
  .filter(f => {
    const name = f.name || f.filename || '';
    return name.toLowerCase().endsWith('.csv');
  });

if (files.length === 0) {
  throw new Error('No hay archivos .csv en /upload todavia. Revisa que Mercado Pago haya depositado el reporte.');
}

files.sort((a, b) => {
  const na = a.name || a.filename || '';
  const nb = b.name || b.filename || '';
  return nb.localeCompare(na);
});

const elegido = files[0];
const nombre = elegido.name || elegido.filename;

return [{ json: { path: '/upload/' + nombre, filename: nombre } }];

// Convierte el binario descargado a texto y parsea el CSV (separado por ';').
const item = $input.first();
const binKeys = Object.keys(item.binary || {});
const propName = binKeys.includes('data') ? 'data' : (binKeys[0] || 'data');

const buffer = await this.helpers.getBinaryDataBuffer(0, propName);
const text = buffer.toString('utf-8');

const lines = text.split(/\r?\n/).filter(l => l.trim().length > 0);
if (lines.length < 2) {
  return [];
}
const headers = lines[0].split(';').map(h => h.trim());

const rows = lines.slice(1).map(line => {
  const cols = line.split(';');
  const obj = {};
  headers.forEach((h, i) => { obj[h] = cols[i] !== undefined ? cols[i].trim() : null; });
  return obj;
});

return rows.map(r => ({ json: r }));

// Arma un unico INSERT ... ON CONFLICT DO NOTHING con todas las filas,
// usando SOURCE_ID como clave de idempotencia (no duplica si el webhook llega dos veces).
const items = $input.all();

if (items.length === 0) {
  return [{ json: { query: 'SELECT 1;', note: 'CSV sin filas de datos.' } }];
}

const esc = v => (v === null || v === undefined || v === '') ? 'NULL' : ("'" + String(v).replace(/'/g, "''") + "'");
const num = v => (v === null || v === undefined || v === '') ? '0' : String(v);

const values = items.map(item => {
  const r = item.json;
  return '(' + esc(r.SOURCE_ID) + ', ' + esc(r.PAYMENT_METHOD_TYPE) + ', ' + esc(r.TRANSACTION_TYPE) + ', ' +
    num(r.TRANSACTION_AMOUNT) + ', ' + esc(r.TRANSACTION_DATE) + ', ' + num(r.FEE_AMOUNT) + ', ' +
    esc(r.SETTLEMENT_DATE) + ', ' + num(r.REAL_AMOUNT) + ', ' + num(r.TAXES_AMOUNT) + ', ' +
    esc(r.BUSINESS_UNIT) + ', ' + esc(r.SUB_UNIT) + ', ' + esc(r.MONEY_RELEASE_DATE) + ')';
}).join(',\n');

const query = 'INSERT INTO mercadopago_settlements ' +
  '(source_id, payment_method_type, transaction_type, transaction_amount, transaction_date, ' +
  'fee_amount, settlement_date, real_amount, taxes_amount, business_unit, sub_unit, money_release_date) ' +
  'VALUES\n' + values + '\nON CONFLICT (source_id) DO NOTHING ' +
  'RETURNING source_id;';

return [{ json: { query, filas_en_csv: items.length } }];
